python3 << 'PYEOF'
import os, re
from collections import defaultdict

REPO = "/bench/repo"

# Persistent entity types (table-backed structs in store/)
ENTITIES = [
    "User", "Memo", "Attachment", "UserSetting", "InstanceSetting",
    "IdentityProvider", "Inbox", "Reaction", "MemoRelation", "MemoShare",
]

# Data layer: store package and subpackages, plus proto store definitions
DATA_LAYER_PREFIXES = (
    "store/",
    "proto/store/",
    "proto/gen/store/",
)

def is_data_layer(path):
    rel = os.path.relpath(path, REPO).replace("\\", "/")
    return rel.startswith(DATA_LAYER_PREFIXES) or rel == "store"

def go_package_dir(filepath):
    """Return Go package path like server/router/api/v1 from file path."""
    rel = os.path.relpath(filepath, REPO).replace("\\", "/")
    return os.path.dirname(rel)

def collect_go_files():
    files = []
    for root, dirs, filenames in os.walk(REPO):
        # skip .git, web, node_modules
        dirs[:] = [d for d in dirs if d not in {'.git', 'node_modules', 'dist'}]
        for fn in filenames:
            if fn.endswith('.go'):
                files.append(os.path.join(root, fn))
    return files

# Patterns for referencing store entities
def entity_patterns(entity):
    return [
        re.compile(r'\bstore\.' + entity + r'\b'),
        re.compile(r'\[\]\*store\.' + entity + r'\b'),
        re.compile(r'\[\]store\.' + entity + r'\b'),
        re.compile(r'\*store\.' + entity + r'\b'),
    ]

entity_pats = {e: entity_patterns(e) for e in ENTITIES}

# Also check storepb proto entities
PROTO_ENTITIES = []
proto_dir = os.path.join(REPO, "proto/store")
if os.path.isdir(proto_dir):
    for fn in os.listdir(proto_dir):
        if fn.endswith('.proto'):
            # read message names
            with open(os.path.join(proto_dir, fn)) as f:
                content = f.read()
            for m in re.finditer(r'^message\s+(\w+)', content, re.M):
                PROTO_ENTITIES.append(m.group(1))

proto_pats = {}
for e in PROTO_ENTITIES:
    proto_pats[e] = [
        re.compile(r'\bstorepb\.' + e + r'\b'),
        re.compile(r'\*storepb\.' + e + r'\b'),
        re.compile(r'store\.' + e + r'\b'),  # unlikely
    ]

results = {e: set() for e in ENTITIES}
proto_results = {e: set() for e in PROTO_ENTITIES}

for fp in collect_go_files():
    rel = os.path.relpath(fp, REPO).replace("\\", "/")
    if is_data_layer(fp):
        continue
    try:
        with open(fp, encoding='utf-8', errors='ignore') as f:
            content = f.read()
    except Exception:
        continue
    pkg = go_package_dir(fp)
    for entity, pats in entity_pats.items():
        if any(p.search(content) for p in pats):
            results[entity].add(pkg)
    for entity, pats in proto_pats.items():
        if any(p.search(content) for p in pats):
            proto_results[entity].add(pkg)

print("=== Go store.* entity references (external packages) ===")
ranked = sorted(ENTITIES, key=lambda e: (-len(results[e]), e))
for e in ranked:
    pkgs = sorted(results[e])
    print(f"{e}: {len(pkgs)} packages")
    for p in pkgs[:8]:
        print(f"  - {p}")
    if len(pkgs) > 8:
        print(f"  ... +{len(pkgs)-8} more")

print("\n=== storepb proto message references (external packages) ===")
proto_ranked = sorted(PROTO_ENTITIES, key=lambda e: (-len(proto_results[e]), e))
for e in proto_ranked[:15]:
    print(f"{e}: {len(proto_results[e])} packages")

print("\nProto entities:", PROTO_ENTITIES)
PYEOF

