perl -e '
use strict; use warnings;
my $REPO = "/bench/repo";
my @ENTITIES = qw(User Memo Attachment UserSetting InstanceSetting IdentityProvider Inbox Reaction MemoRelation MemoShare);

sub is_data_layer {
  my ($rel) = @_;
  return 1 if $rel =~ m{^(store/|proto/store/|proto/gen/store/)};
  return 0;
}

my %results;
for my $e (@ENTITIES) { $results{$e} = {}; }

opendir(my $dh, $REPO) or die $!;
my @stack = map { "$REPO/$_" } grep { $_ ne "." && $_ ne ".." } readdir($dh);
closedir $dh;

while (@stack) {
  my $path = pop @stack;
