perl -e '
use strict; use warnings;
my $REPO = "/bench/repo";
my @ENTITIES = qw(User Memo Attachment UserSetting InstanceSetting IdentityProvider Inbox Reaction MemoRelation MemoShare UserIdentity);

sub is_data_layer {
  my ($rel) = @_;
  return 1 if $rel =~ m{^(store/|proto/store/|proto/gen/store/)};
  return 0;
}

my %store_results; my %pb_results;
for my $e (@ENTITIES) { $store_results{$e} = {}; $pb_results{$e} = {}; }

opendir(my $dh, $REPO) or die $!;
my @stack = map { "$REPO/$_" } grep { $_ ne "." && $_ ne ".." } readdir($dh);
closedir $dh;

while (@stack) {
  my $path = pop @stack;
  next if $path =~ m{/(?:\.git|node_modules|dist)(?:/|$)};
  if (-d $path) {
    opendir(my $d, $path) or next;
    push @stack, map { "$path/$_" } grep { $_ ne "." && $_ ne ".." } readdir($d);
    closedir $d;
    next;
  }
  next unless $path =~ /\.go$/;
  my $rel = $path; $rel =~ s{^\Q$REPO\E/?}{};
  next if is_data_layer($rel);
  open(my $fh, "<", $path) or next;
  local $/; my $content = <$fh>; close $fh;
  (my $pkg = $rel) =~ s{/[^/]+$}{};
  for my $e (@ENTITIES) {
    $store_results{$e}{$pkg} = 1 if $content =~ /\bstore\.$e\b/;
    $pb_results{$e}{$pkg} = 1 if $content =~ /\bstorepb\.$e\b/;
  }
}

print "entity | store pkgs | storepb pkgs | combined\n";
for my $e (sort { ((keys %{$store_results{$b}})+(keys %{$pb_results{$b}})) <=> ((keys %{$store_results{$a}})+(keys %{$pb_results{$a}})) || $a cmp $b } @ENTITIES) {
  my %combined = (%{$store_results{$e}}, %{$pb_results{$e}});
  printf "%s | %d | %d | %d\n", $e, scalar(keys %{$store_results{$e}}), scalar(keys %{$pb_results{$e}}), scalar(keys %combined);
}
'

