perl -e '
use strict; use warnings;
my $REPO = "/bench/repo";
# Top-level proto entity/payload types from proto/store
my @PROTO_ENTITIES = qw(IdentityProvider InboxMessage InstanceSetting UserSetting MemoPayload AttachmentPayload);

sub is_data_layer {
  my ($rel) = @_;
  return 1 if $rel =~ m{^(store/|proto/store/|proto/gen/store/)};
  return 0;
}

my %results;
for my $e (@PROTO_ENTITIES) { $results{$e} = {}; }

opendir(my $dh, $REPO) or die $!;
my @stack = map { "$REPO/$_" } grep { $_ ne "." && $_ ne ".." } readdir($dh);
closedir $dh;

while (@stack) {
  my $path = pop @stack;
  next if $path =~ m{/(?:\.git|node_modules|dist)(?:/|$)};
  if (-d $path) {
    opendir(my $d, $path) or next;
    push @stack, map { "$path/$_" } grep { $_ ne "." && $_ ne ".." } readdir($d);
    closedir $d;
    next;
  }
  next unless $path =~ /\.go$/;
  my $rel = $path; $rel =~ s{^\Q$REPO\E/?}{};
  next if is_data_layer($rel);
  open(my $fh, "<", $path) or next;
  local $/; my $content = <$fh>; close $fh;
  (my $pkg = $rel) =~ s{/[^/]+$}{};
  for my $e (@PROTO_ENTITIES) {
    $results{$e}{$pkg} = 1 if $content =~ /\bstorepb\.$e\b/;
  }
}

for my $e (sort { (keys %{$results{$b}}) <=> (keys %{$results{$a}}) || $a cmp $b } @PROTO_ENTITIES) {
  my @pkgs = sort keys %{$results{$e}};
  print "$e: ", scalar(@pkgs), " -> @pkgs\n";
}
'

