perl -e '
use strict; use warnings;
my $REPO = "/bench/repo";
my @ENTITIES = qw(User Memo Attachment UserSetting InstanceSetting IdentityProvider Inbox Reaction MemoRelation MemoShare UserIdentity);

sub is_data_layer { my ($rel)=@_; return 1 if $rel =~ m{^(store/|proto/store/|proto/gen/store/)}; 0; }
sub is_test_pkg { my ($pkg)=@_; return 1 if $pkg =~ m{/test$} || $pkg =~ m{_test$}; 0; }

my %results; for my $e (@ENTITIES) { $results{$e}={}; }
opendir(my $dh, $REPO) or die $!; my @stack = map { "$REPO/$_" } grep { $_ ne "." && $_ ne ".." } readdir($dh); closedir $dh;
while (@stack) {
  my $path = pop @stack;
  next if $path =~ m{/(?:\.git|node_modules|dist)(?:/|$)};
  if (-d $path) { opendir(my $d,$path) or next; push @stack, map { "$path/$_" } grep { $_ ne "." && $_ ne ".." } readdir($d); closedir $d; next; }
  next unless $path =~ /\.go$/ && $path !~ /_test\.go$/;
  my $rel=$path; $rel=~s{^\Q$REPO\E/?}{}; next if is_data_layer($rel);
  open(my $fh,"<",$path) or next; local $/; my $c=<$fh>; close $fh;
  (my $pkg=$rel)=~s{/[^/]+$}{}; next if is_test_pkg($pkg);
  for my $e (@ENTITIES) { $results{$e}{$pkg}=1 if $c =~ /\bstore\.$e\b/; }
}
print "Non-test production packages only:\n";
for my $e (sort { (keys%{$results{$b}})<=> (keys%{$results{$a}}) || $a cmp $b } @ENTITIES) {
  my @p=sort keys %{$results{$e}}; print "$e: @p\n" if @p;
}
'

