  for my $e (@ENTITIES) { $results{$e}{$pkg}=1 if $c =~ /\bstore\.$e\b/; }
}
print "Non-test production packages only:\n";
for my $e (sort { (keys%{$results{$b}})<=> (keys%{$results{$a}}) || $a cmp $b } @ENTITIES) {
  my @p=sort keys %{$results{$e}}; print "$e: @p\n" if @p;
}
'

